package com.anonymous.entity;

import jakarta.persistence.*;
import lombok.*;
import lombok.experimental.FieldDefaults;

// One searchable piece of a knowledge-base document. The id is generated by the service because it is
// also the point id in Qdrant; chunks are rebuilt with their document, so they carry no audit columns.
@Entity
@Table(name = "kb_chunk")
@Getter
@Setter
@Builder
@AllArgsConstructor
@NoArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE)
public class KbChunk {

    @Id
    @Column(name = "id", length = 36)
    String id;

    @Column(name = "document_id", nullable = false, length = 36)
    String documentId;

    @Column(name = "chunk_index", nullable = false)
    Integer chunkIndex;

    // "Section > Sub-section" the chunk was cut from
    @Column(name = "heading_path", length = 500)
    String headingPath;

    @Column(name = "content", nullable = false, columnDefinition = "TEXT")
    String content;

    @Column(name = "content_hash", nullable = false, columnDefinition = "CHAR(64)")
    String contentHash;

}
